import * as ev from 'node:events';
const E: any = ev;
function main(): void {
  console.log('usingDomains', typeof E.usingDomains, E.usingDomains);
  console.log('defaultMaxListeners', typeof E.defaultMaxListeners, E.defaultMaxListeners);
  console.log('captureRejections', typeof E.captureRejections, E.captureRejections);
  console.log('errorMonitor', typeof E.errorMonitor, String(E.errorMonitor));
  const r: any = new E.EventEmitterAsyncResource({ name: 'probe' });
  console.log('EventEmitterAsyncResource', typeof E.EventEmitterAsyncResource, typeof r, typeof r.asyncId, typeof r.triggerAsyncId, typeof r.emitDestroy, typeof r.on);
  try { new E.EventEmitterAsyncResource({}); console.log('no error'); } catch (e: any) { console.log('nameError', e.name, e.code); }
}
